// Confirm these paths against a captured Cal.com webhook before activation.
const root=$json.body ?? $json; const p=root.payload ?? root;
const event=String(root.triggerEvent ?? root.event ?? '').toLowerCase();
const status=event.includes('cancel')?'cancelled':event.includes('resched')?'rescheduled':'created';
const uid=p.uid ?? p.bookingUid ?? p.id; if(!uid) throw new Error('Cal.com payload mapping required: booking UID not found');
const email=p.attendees?.[0]?.email ?? p.attendee?.email ?? p.email ?? null;
const name=p.attendees?.[0]?.name ?? p.attendee?.name ?? p.name ?? null;
const clientSlug=p.metadata?.client_slug ?? p.metadata?.clientSlug ?? 'abc-roofing';
return [{json:{client_slug:clientSlug,provider_booking_uid:String(uid),booking_status:status,start_time:p.startTime ?? p.start_time ?? null,end_time:p.endTime ?? p.end_time ?? null,attendee_email:email?String(email).trim().toLowerCase():null,attendee_name:name,event_type:p.eventTitle ?? p.eventType?.title ?? null,raw_payload:JSON.stringify(root)}}];
